/* -------------------------------------------------------------------------------------------------
 * Types
 * -----------------------------------------------------------------------------------------------*/

export type StackFrameKind = "app" | "dependency" | "internal"

export interface StackFrame {
  /** Function name, `<anonymous>` when there is none. */
  fn?: string
  file?: string
  line?: number
  column?: number
  async?: boolean
  kind: StackFrameKind
  /** Package name for dependency frames, read from the `node_modules` path. */
  pkg?: string
  /** The original line. */
  raw: string
}

export interface StackTraceProps extends Omit<React.ComponentProps<"div">, "children"> {
  /** A raw stack (`error.stack`). V8 (Node, Chrome) and Firefox/Safari formats are parsed. */
  trace: string
  /** Override the error name read from the first line. */
  name?: string
  /** Override the error message read from the first lines. */
  message?: React.ReactNode
  /** Project root, stripped from paths so `src/lib/stripe.ts` reads instead of the full path. */
  appRoot?: string
  /** Decide which frames are yours. Default: anything outside `node_modules` and runtime internals. */
  isAppFrame?: (frame: StackFrame) => boolean
  /** Link for a frame, for example `vscode://file/${file}:${line}:${column}`. */
  getFrameHref?: (frame: StackFrame) => string | undefined
  /** Called when a frame location is clicked. Use instead of links to open an editor panel. */
  onFrameClick?: (frame: StackFrame) => void
  /** Open every folded group of dependency frames. Default false. */
  defaultExpanded?: boolean
  /** `card` has its own surface and header. `compact` is just the frames, for embedding. */
  variant?: "card" | "compact"
}

export interface ParsedStack {
  name?: string
  message?: string
  frames: StackFrame[]
}

/* -------------------------------------------------------------------------------------------------
 * Parsing
 * -----------------------------------------------------------------------------------------------*/

const V8_FRAME = /^\s*at\s+(?:(async)\s+)?(?:(.*?)\s+\((.*)\)|(.*))\s*$/

const LOCATION = /^(.*?):(\d+)(?::(\d+))?$/

function splitLocation(location: string) {
  const clean = location
    .replace(/^file:\/\//, "")
    .replace(/^webpack-internal:\/\/\/(\([^)]*\)\/)?/, "")
  const m = clean.match(LOCATION)
  if (!m) return { file: clean || undefined }
  return { file: m[1], line: Number(m[2]), column: m[3] ? Number(m[3]) : undefined }
}

function classify(file: string | undefined): { kind: StackFrameKind; pkg?: string } {
  if (!file) return { kind: "internal" }
  if (/^(node:|internal\/)/.test(file)) return { kind: "internal", pkg: "node" }
  if (/^(native|<anonymous>)/.test(file)) return { kind: "internal", pkg: "runtime" }
  const nm = file.match(/node_modules\/(?:\.pnpm\/[^/]+\/node_modules\/)?((?:@[^/]+\/)?[^/]+)/)
  if (nm) return { kind: "dependency", pkg: nm[1] }
  return { kind: "app" }
}

const GECKO_FRAME = /^\s*(.*?)@(.*?)(?::(\d+))?(?::(\d+))?\s*$/

/** Parses `error.stack` text into a name, message and frames. */
export function parseStackTrace(trace: string): ParsedStack {
  const lines = trace.replace(/\r\n/g, "\n").split("\n")
  const frames: StackFrame[] = []
  const head: string[] = []
  for (const raw of lines) {
    const v8 = raw.match(V8_FRAME)
    if (v8) {
      const location = v8[3] ?? v8[4] ?? ""
      const fn = v8[2]?.replace(/^new\s+/, "new ")
      const loc = splitLocation(location)
      frames.push({
        fn: fn || undefined,
        async: v8[1] === "async",
        raw: raw.trim(),
        ...loc,
        ...classify(loc.file),
      })
      continue
    }
    // Firefox and Safari: `fn@url:line:col`, no spaces before the location.
    const gecko = /^[^\s@]*@\S+:\d+/.test(raw.trim()) ? raw.trim().match(GECKO_FRAME) : null
    if (gecko) {
      const loc = splitLocation(
        `${gecko[2]}${gecko[3] ? `:${gecko[3]}` : ""}${gecko[4] ? `:${gecko[4]}` : ""}`,
      )
      frames.push({ fn: gecko[1] || undefined, raw: raw.trim(), ...loc, ...classify(loc.file) })
      continue
    }
    if (frames.length === 0 && raw.trim()) head.push(raw)
  }
  const first = head.join("\n")
  const m = first.match(/^([\w$.]*(?:Error|Exception|Warning)|[A-Z][\w$]*):\s?([\s\S]*)$/)
  return m ? { name: m[1], message: m[2], frames } : { message: first || undefined, frames }
}

type Group =
  | { type: "app"; frame: StackFrame; index: number }
  | { type: "folded"; frames: StackFrame[]; key: string }

function groupFrames(frames: StackFrame[]): Group[] {
  const groups: Group[] = []
  frames.forEach((frame, index) => {
    if (frame.kind === "app") {
      groups.push({ type: "app", frame, index })
      return
    }
    const last = groups.at(-1)
    if (last?.type === "folded") last.frames.push(frame)
    else groups.push({ type: "folded", frames: [frame], key: `f${index}` })
  })
  return groups
}

/* -------------------------------------------------------------------------------------------------
 * Frames
 * -----------------------------------------------------------------------------------------------*/

function displayPath(file: string, appRoot?: string) {
  let path = file
  if (appRoot) {
    const root = appRoot.endsWith("/") ? appRoot : `${appRoot}/`
    if (path.startsWith(root)) path = path.slice(root.length)
  }
  // Long dependency paths keep only what follows the package folder.
  const nm = path.lastIndexOf("node_modules/")
  if (nm >= 0) path = path.slice(nm + "node_modules/".length)
  return path
}

function Location({
  frame,
  appRoot,
  getFrameHref,
  onFrameClick,
}: Pick<StackTraceProps, "appRoot" | "getFrameHref" | "onFrameClick"> & { frame: StackFrame }) {
  if (!frame.file) return null
  const path = displayPath(frame.file, appRoot)
  const slash = path.lastIndexOf("/")
  const dir = slash >= 0 ? path.slice(0, slash + 1) : ""
  const base = slash >= 0 ? path.slice(slash + 1) : path
  const position = `${frame.line !== undefined ? `:${frame.line}` : ""}${frame.column !== undefined ? `:${frame.column}` : ""}`
  const text = `${path}${position}`
  // The file and line are what you open, so they never cut: the folder gives way from its start
  // ("…/lib/stripe.ts:42:31"), its inner run isolated so slashes keep their order.
  const parts = (
    <>
      {dir ? (
        <span className="text-(color:--chatcn-fg-subtle) min-w-[2ch] truncate [direction:rtl]">
          <span className="[direction:ltr] [unicode-bidi:isolate]">{dir}</span>
        </span>
      ) : null}
      <span className="flex max-w-full min-w-0 shrink-0">
        <span className="min-w-0 truncate">{base}</span>
        {position ? (
          <span className="text-(color:--chatcn-fg-subtle) shrink-0 tabular-nums">{position}</span>
        ) : null}
      </span>
    </>
  )
  const linkClass = cn(
    "chatcn-focus rounded-(--chatcn-radius-xs) flex min-w-0 underline-offset-2",
    "decoration-(color:--chatcn-border-strong) hover:text-(color:--chatcn-fg) hover:underline",
  )
  const link = getFrameHref?.(frame)
  if (link) {
    return (
      <a
        href={link}
        aria-label={text}
        className={linkClass}
        onClick={() => onFrameClick?.(frame)}
        title={frame.file}
      >
        {parts}
      </a>
    )
  }
  if (onFrameClick) {
    return (
      <button
        type="button"
        aria-label={text}
        className={cn(linkClass, "text-start")}
        onClick={() => onFrameClick(frame)}
        title={frame.file}
      >
        {parts}
      </button>
    )
  }
  return (
    <span className="flex min-w-0" title={frame.file}>
      <span className="sr-only">{text}</span>
      <span aria-hidden="true" className="flex min-w-0">
        {parts}
      </span>
    </span>
  )
}

function FrameRow({
  frame,
  origin,
  ...rest
}: Pick<StackTraceProps, "appRoot" | "getFrameHref" | "onFrameClick"> & {
  frame: StackFrame
  origin?: boolean
}) {
  const app = frame.kind === "app"
  return (
    <li
      data-slot="stack-trace-frame"
      data-frame-kind={frame.kind}
      data-origin={origin ? "" : undefined}
      className={cn(
        // Frames start on the message's column (14 px inset + 16 px glyph column + 10 px gap).
        "relative flex min-h-7 flex-wrap items-baseline gap-x-3 gap-y-0.5 py-1 ps-10 pe-3.5",
        origin && "bg-(color:--chatcn-fill)",
      )}
    >
      {origin ? (
        <span aria-hidden="true" className="bg-(color:--chatcn-fg) absolute inset-y-0 start-0 w-0.5" />
      ) : null}
      <span
        className={cn(
          "shrink-0 font-mono",
          app ? "text-(color:--chatcn-fg) font-medium" : "text-(color:--chatcn-fg-subtle)",
        )}
      >
        {frame.async ? <span className="text-(color:--chatcn-fg-subtle) font-normal">async </span> : null}
        {frame.fn ?? "<anonymous>"}
      </span>
      <span
        className={cn(
          "flex min-w-0 flex-1 font-mono",
          app ? "text-(color:--chatcn-fg-muted)" : "text-(color:--chatcn-fg-subtle)",
        )}
      >
        <Location frame={frame} {...rest} />
      </span>
      {origin ? <span className="sr-only">Where the error was thrown</span> : null}
    </li>
  )
}

interface IconProps extends SVGAttributes<SVGSVGElement> {
  /** Width and height. Number means px. Default 24. */
  size?: number | string
  /** Stroke width in viewBox units (24 grid). Default 1.5. */
  strokeWidth?: number | string
  /** Keep the rendered stroke at `strokeWidth` px at any size. */
  absoluteStrokeWidth?: boolean
  /** Stroke color. Default currentColor. */
  color?: string
  /** Accessible name. Renders <title> and sets role="img"; without it the icon is aria-hidden. */
  title?: string
}

type Icon = ForwardRefExoticComponent<IconProps & RefAttributes<SVGSVGElement>>

/** Shape elements an icon may contain. */
type IconElement = "path" | "circle" | "rect" | "ellipse" | "line" | "polyline" | "polygon"

/** An icon's drawing: a flat list of [element, attributes] pairs, lucide compatible. */
type IconNode = ReadonlyArray<readonly [IconElement, Readonly<Record<string, string>>]>

const toPascal = (name: string): string =>
  name
    .split("-")
    .map((part) => part.charAt(0).toUpperCase() + part.slice(1))
    .join("")

/**
 * Builds a React icon component from an icon node.
 * `name` is the kebab-case icon name, used for the class `chatcn-icon-<name>` and displayName.
 */
function createIcon(name: string, iconNode: IconNode): Icon {
  // biome-ignore lint/correctness/noComponentHookFactories: runs once per icon at module load
  const Component = forwardRef<SVGSVGElement, IconProps>(function ChatcnIcon(
    {
      size = 24,
      strokeWidth = 1.5,
      absoluteStrokeWidth = false,
      color = "currentColor",
      title,
      className,
      children,
      ...rest
    },
    ref,
  ) {
    const stroke = absoluteStrokeWidth
      ? (Number(strokeWidth) * 24) / Number.parseFloat(String(size))
      : strokeWidth
    const labelled = Boolean(title || rest["aria-label"] || rest["aria-labelledby"])
    return createElement(
      "svg",
      {
        ref,
        xmlns: "http://www.w3.org/2000/svg",
        width: size,
        height: size,
        viewBox: "0 0 24 24",
        fill: "none",
        stroke: color,
        strokeWidth: stroke,
        strokeLinecap: "round",
        strokeLinejoin: "round",
        "data-slot": "icon",
        className: className
          ? `chatcn-icon chatcn-icon-${name} ${className}`
          : `chatcn-icon chatcn-icon-${name}`,
        ...(labelled ? { role: "img" } : { "aria-hidden": true }),
        ...rest,
      },
      title ? createElement("title", null, title) : null,
      ...iconNode.map(([tag, attrs], i) => createElement(tag, { key: i, ...attrs })),
      children,
    )
  })
  Component.displayName = `${toPascal(name)}Icon`
  return Component
}

const iconNode: IconNode = [
