]

const ChevronRightIcon: Icon = /* @__PURE__ */ createIcon("chevron-right", iconNode)

function foldedLabel(frames: StackFrame[]) {
  const pkgs = [...new Set(frames.map((f) => f.pkg).filter(Boolean))]
  const count = `${frames.length} ${frames.length === 1 ? "frame" : "frames"}`
  if (pkgs.length === 0) return count
  const names =
    pkgs.length > 2 ? `${pkgs.slice(0, 2).join(", ")} and ${pkgs.length - 2} more` : pkgs.join(", ")
  return `${count} from ${names}`
}

function FoldedFrames({
  frames,
  defaultOpen,
  ...rest
}: Pick<StackTraceProps, "appRoot" | "getFrameHref" | "onFrameClick"> & {
  frames: StackFrame[]
  defaultOpen: boolean
}) {
  const [open, setOpen] = React.useState(defaultOpen)
  const id = React.useId()
  return (
    <li data-slot="stack-trace-folded">
      <button
        type="button"
        aria-expanded={open}
        aria-controls={id}
        onClick={() => setOpen((o) => !o)}
        className={cn(
          "text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) hover:text-(color:--chatcn-fg-muted) flex h-7 w-full items-center gap-2.5 ps-3.5 pe-3.5 text-start",
          "focus-visible:outline-(color:--chatcn-accent) outline-none focus-visible:outline-2 focus-visible:-outline-offset-2",
        )}
      >
        {/* The chevron sits in the same 16 px column as the error glyph above. */}
        <span className="grid size-4 shrink-0 place-items-center">
          <ChevronRightIcon
            aria-hidden="true"
            className={cn("size-3.5 rtl:-scale-x-100", open && "rotate-90 rtl:-rotate-90")}
          />
        </span>
        <span className="truncate">{foldedLabel(frames)}</span>
      </button>
      {open ? (
        <ul id={id} className="text-[0.75rem]/[1rem]">
          {frames.map((frame, i) => (
            <FrameRow key={i} frame={frame} {...rest} />
          ))}
        </ul>
      ) : null}
    </li>
  )
}

const iconNode2: IconNode = [
  ["path", {"d":"M3 12a9 9 0 1 0 18 0 9 9 0 1 0-18 0"}],
  ["path", {"d":"m9 9 6 6"}],
