/** Copy swaps to a check with a 150 ms blur crossfade, holds for 1.5 s and announces itself. */
function CopyButton({
  value,
  label = "Copy",
  onCopy,
  onClick,
  children,
  size = "icon-sm",
  className,
  ...props
}: CopyButtonProps) {
  // A counter, not a flag: copying again while the check shows restarts the 1.5 s hold.
  const [copies, setCopies] = React.useState(0)
  const [copied, setCopied] = React.useState(false)
  React.useEffect(() => {
    if (!copies) return
    setCopied(true)
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copies])

  // Reduced motion keeps the crossfade and drops the scale and blur.
  const layer = cn(
    "ease-(--chatcn-ease-out) absolute transition-[opacity,scale,filter] duration-150",
    "motion-reduce:scale-100 motion-reduce:blur-none motion-reduce:transition-opacity",
  )
  return (
    <Button
      {...props}
      size={size}
      aria-label={children ? undefined : copied ? "Copied" : label}
      onClick={(event) => {
        // Compose with handlers injected by wrappers such as Tooltip instead of replacing them.
        onClick?.(event)
        if (event.defaultPrevented) return
        const text = typeof value === "function" ? value() : value
        navigator.clipboard
          ?.writeText(text)
          .then(() => {
            setCopies((n) => n + 1)
            onCopy?.(text)
          })
          // Clipboard access can be denied (insecure context, permissions). Stay quiet and unchanged.
          .catch(() => {})
      }}
      className={cn("relative", className)}
    >
      {children ? (
        <>
          <span className="relative grid size-3.5 place-items-center">
            <CopyIcon
              className={cn(
                layer,
                copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
              )}
            />
            <CheckIcon
              className={cn(
                layer,
                copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
              )}
            />
          </span>
          {children}
        </>
      ) : null}
      {children ? null : (
        <>
          <CopyIcon
            className={cn(
              layer,
              copied ? "scale-75 opacity-0 blur-[2px]" : "scale-100 opacity-100",
            )}
          />
          <CheckIcon
            className={cn(
              layer,
              copied ? "scale-100 opacity-100" : "scale-75 opacity-0 blur-[2px]",
            )}
          />
        </>
      )}
      <span aria-live="polite" className="sr-only">
        {copied ? "Copied" : ""}
      </span>
    </Button>
  )
}

/* -------------------------------------------------------------------------------------------------
 * StackTrace
 * -----------------------------------------------------------------------------------------------*/

export function StackTrace({
  trace,
  name: nameProp,
  message: messageProp,
  appRoot,
  isAppFrame,
  getFrameHref,
  onFrameClick,
  defaultExpanded = false,
  variant = "card",
  className,
  ...props
}: StackTraceProps) {
  const parsed = React.useMemo(() => {
    const p = parseStackTrace(trace)
    if (!isAppFrame) return p
    return {
      ...p,
      frames: p.frames.map((f) => ({
        ...f,
        kind: isAppFrame(f)
          ? ("app" as const)
          : f.kind === "app"
            ? ("dependency" as const)
            : f.kind,
      })),
    }
  }, [trace, isAppFrame])

  const name = nameProp ?? parsed.name
  const message = messageProp ?? parsed.message
  const groups = groupFrames(parsed.frames)
  const origin = parsed.frames.findIndex((f) => f.kind === "app")
  const shared = { appRoot, getFrameHref, onFrameClick }
  const card = variant === "card"

  const list =
    parsed.frames.length === 0 ? (
      <p className="text-[0.75rem]/[1rem] text-(color:--chatcn-fg-subtle) py-2 ps-10 pe-3.5">No stack frames</p>
    ) : (
      <ol aria-label="Stack frames" className="text-[0.75rem]/[1rem] py-1">
        {groups.map((group) =>
          group.type === "app" ? (
            <FrameRow
              key={`a${group.index}`}
              frame={group.frame}
              origin={group.index === origin}
              {...shared}
            />
          ) : (
            <FoldedFrames
              key={group.key}
              frames={group.frames}
              defaultOpen={defaultExpanded || origin < 0}
              {...shared}
            />
          ),
        )}
      </ol>
    )

  if (!card) {
    return (
      <div
        data-slot="stack-trace"
        data-variant="compact"
        className={cn("min-w-0", className)}
        {...props}
      >
        {list}
      </div>
    )
  }

  return (
    // biome-ignore lint/a11y/useSemanticElements: a fieldset is for form controls
    <div
      data-slot="stack-trace"
      data-variant="card"
      role="group"
      aria-label={name ? `${name} stack trace` : "Stack trace"}
      className={cn(
        "rounded-(--chatcn-radius-lg) bg-(color:--chatcn-card) shadow-(--chatcn-shadow-sm) overflow-hidden forced-colors:outline-1 forced-colors:outline-solid",
        className,
      )}
      {...props}
    >
      <div className="border-(color:--chatcn-border)/70 flex items-start gap-2.5 border-b py-3 ps-3.5 pe-2">
        <CircleXIcon aria-hidden="true" className="text-(color:--chatcn-red) mt-0.5 size-4 shrink-0" />
        <div className="flex min-w-0 flex-1 flex-col gap-0.5">
          {name ? <span className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-red) font-medium">{name}</span> : null}
          {message ? (
            <p className="text-[0.8125rem]/[1.25rem] text-(color:--chatcn-fg) font-mono [overflow-wrap:anywhere] whitespace-pre-wrap">
              {message}
            </p>
          ) : null}
        </div>
        <CopyButton
          size="icon-xs"
          label="Copy stack trace"
          value={trace}
          className="-mt-0.5 pointer-coarse:size-11"
        />
      </div>
      {list}
    </div>
  )
}

export default StackTrace

